function engravingDistance(surface, angle, face) {
  const x = angle - surface.angle;
  const y = (face - surface.face) * surface.height / surface.faceSpan;
  let nearest = Infinity, inside = false;
  for (const [x0,y0,x1,y1] of surface.segments) {
    const dx=x1-x0, dy=y1-y0;
    const t=w(((x-x0)*dx+(y-y0)*dy)/(dx*dx+dy*dy),0,1);
    nearest=Math.min(nearest,(x-x0-t*dx)**2+(y-y0-t*dy)**2);
    if((y0>y)!==(y1>y) && x < x0+dx*(y-y0)/dy) inside=!inside;
  }
  return (inside?-1:1)*Math.sqrt(nearest);
}

function engravedSurfacePoint(surface, angle, face) {
  const distance=engravingDistance(surface,angle,face);
  const radial=Math.cos(face), axial=Math.sin(face);
  const bandWidth=surface.bandWidth||LA.aw;
  const length=Math.hypot(bandWidth*radial, LA.th*axial);
  const depth=.018 * (1-Q(-.009,.008,distance));
  const radius=1+LA.th*radial-depth*bandWidth*radial/length;
  return [radius*Math.cos(angle),radius*Math.sin(angle),
    bandWidth*axial-depth*LA.th*axial/length];
}

function sampleEngravedBand(surface, angle, face) {
  const point=engravedSurfacePoint(surface,angle,face);
  const da=engravedSurfacePoint(surface,angle+.001,face).map((v,i)=>v-point[i]);
  const df=engravedSurfacePoint(surface,angle,face+.001).map((v,i)=>v-point[i]);
  const normal=[da[1]*df[2]-da[2]*df[1],da[2]*df[0]-da[0]*df[2],da[0]*df[1]-da[1]*df[0]];
  const length=Math.hypot(...normal)||1;
  const distance=engravingDistance(surface,angle,face);
  return {
    point, normal: normal.map(v=>v/length),
    groove: 1-Q(-.008,.003,distance),
    bevel: Q(-.005,.002,distance)*(1-Q(.005,.012,distance))
  };
}

